-- Каталог донесений. Собрано tools/reports/build.js из tools/reports/*.js — руками не править.
on conflict (id) do update set side = excluded.side, cat = excluded.cat, chain = excluded.chain, w = excluded.w, def = excluded.def, data = excluded.data, active = true;
-- убранные из каталога больше не выпадают
update public.report_catalog set active = false where cat <> 'site' and id not in ('r_strike', 'r_spy', 'r_refugees', 'r_debris', 'r_memorial', 'r_auditor', 'r_padawan', 'r_leave', 'r_smugglers', 'r_fever', 'r_harvest', 'r_pirates', 'r_lab', 'r_storm', 'r_loan', 'r_leaflets', 'r_shield', 'r_reporter', 'r_deserter', 'r_guild', 'r_cache', 'r_pacifists', 'r_barman', 'r_meds', 'r_beasts', 'r_beacon', 'r_hutt', 'r_militia', 'r_election', 'r_meteor', 'r_relic', 'r_inventor', 'r_widow', 'r_leak', 'r_brawl', 'r_astromech', 'r_envoy', 'r_sith_rumor', 'r_famine', 'r_grain', 'r_drills', 'r_feast', 'r_crystal_vein', 'r_supply_error', 'r_training', 'r_cantina_sabacc', 'r_water', 'r_strike_due', 'r_spy_double', 'r_refugees_skill', 'r_padawan_temple', 'r_lab_result', 'r_loan_due', 'r_loan_due_small', 'r_hutt_favor', 'r_leaflets_press', 'c_droid_bug', 'c_bank_share', 'c_tf_deal', 'c_prototype', 'c_rep_spy', 'c_workers', 'c_mercs', 'c_wreck', 'c_council_report', 'c_jedi_saboteur', 'c_parts', 'c_scavengers', 'c_commerce_tax', 'c_refugees', 'c_rust', 'c_ion', 'c_bounty', 'c_inspection', 'c_holo_propaganda', 'c_cache', 'c_foundry', 'c_spice', 'c_tactical', 'c_auction', 'c_ruler', 'c_beasts', 'c_independence', 'c_droideka', 'c_tibanna_leak', 'c_duel', 'c_diplomat', 'c_ore_lost', 'c_senator', 'c_virus', 'c_quake', 'c_cyber', 'c_traitor', 'c_hunger', 'c_crystal_market', 'c_droid_drills', 'c_prison', 'c_ruins', 'c_power', 'c_pilots', 'c_banker_party', 'c_dust', 'c_loan', 'c_droid_bug_root', 'c_prototype_result', 'c_rep_spy_deal', 'c_jedi_hunt', 'c_mercs_payday', 'c_prison_leader', 'c_ruins_deep', 'c_loan_due');
