insert into public.report_catalog (id, side, cat, chain, w, def, data) values
('r_strike', 'republic', 'mine', false, 1, 1, '{"title":"Забастовка шахтёров","text":"Шахтёры {planet} бросили смены: говорят, что после налёта дроидов работают по двенадцать часов без надбавки. Бригадиры ждут ответа у ворот штольни.","opts":[{"label":"Выплатить надбавку","cost":{"cr":250},"risk":"sure","bad":0,"outs":[{"p":1,"text":"Шахтёры вернулись в забой с песней — смена работает на совесть.","fx":{"extract":[15,24],"mood":[5,24]}}]},{"label":"Прислать патруль клонов","cost":null,"risk":"gamble","bad":100,"outs":[{"p":6,"text":"Забастовка сорвана, но в посёлке недовольно шепчутся.","fx":{"mood":[-10,48]}},{"p":4,"text":"Дошло до стычки — штольни стоят, рабочие злы.","fx":{"extract":[-20,24],"mood":[-15,48]}}]},{"label":"Пообещать прибавку позже","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Бригадиры согласились подождать — но обещание запомнили.","fx":{"next":"r_strike_due"}}]}]}'::jsonb),
('r_spy', 'republic', 'spy', false, 1, 2, '{"title":"Пойман шпион КНС","text":"Патруль задержал на {planet} техника с передатчиком. Он клянётся, что работает на Торговую федерацию только ради долгов семьи.","opts":[{"label":"Допросить","cost":null,"risk":"luck","bad":0,"outs":[{"p":7,"text":"Шпион выдал тайник сепаратистов в предгорьях.","fx":{"res":{"electronics":40}}},{"p":3,"text":"Он молчал до конца. Время потеряно.","fx":{}}]},{"label":"Перевербовать","cost":{"cr":150},"risk":"sure","bad":0,"outs":[{"p":1,"text":"Техник согласился передавать ложные данные. Посмотрим, что выйдет.","fx":{"next":"r_spy_double"}}]},{"label":"Выслать с планеты","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Шпиона посадили на первый транспорт. Жители спокойнее.","fx":{"mood":[5,24]}}]}]}'::jsonb),
('r_refugees', 'republic', 'refugees', false, 1, 2, '{"title":"Беженцы из Внешнего кольца","text":"К {planet} подошёл старый транспорт: шестьсот беженцев с выжженной колонии. Капитан просит разрешения на посадку.","opts":[{"label":"Принять всех","cost":{"res":{"food":40}},"risk":"sure","bad":0,"outs":[{"p":1,"text":"Беженцы благодарят Республику. Среди них нашлись мастера.","fx":{"mood":[10,48],"next":"r_refugees_skill"}}]},{"label":"Принять только детей и раненых","cost":{"res":{"food":15}},"risk":"sure","bad":0,"outs":[{"p":1,"text":"Половинчатое решение. Кто-то хвалит, кто-то ворчит.","fx":{"mood":[3,24]}}]},{"label":"Отказать","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Транспорт ушёл в гиперпространство. В кантинах говорят о чёрствости властей.","fx":{"mood":[-10,48]}}]}]}'::jsonb),
('r_debris', 'republic', 'debris', false, 1, 1, '{"title":"Обломки на орбите","text":"После вчерашней стычки над {planet} дрейфует обломок фрегата КНС. Сборщики уже кружат вокруг.","opts":[{"label":"Отправить сборщиков","cost":{"cr":100},"risk":"sure","bad":0,"outs":[{"p":1,"text":"Сняли листы дюрастали и уцелевшие узлы.","fx":{"res":{"durasteel":60,"electronics":15}}}]},{"label":"Продать права мусорщикам","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Мусорщики заплатили наличными и улетели довольные.","fx":{"cr":220}}]},{"label":"Обыскать отсеки","cost":null,"risk":"luck","bad":0,"outs":[{"p":3,"text":"В трюме нашёлся исправный дроид-разведчик — перепрошили и поставили в строй.","fx":{"gift":"inf"}},{"p":7,"text":"Отсеки пусты, а мусорщики забрали лучшее, пока мы искали.","fx":{}}]}]}'::jsonb),
('r_memorial', 'republic', 'senate', false, 1, 2, '{"title":"Мемориал павшим","text":"Сенатор сектора просит заложить на {planet} мемориал клонам, павшим при обороне системы. Голонет обещает репортаж.","opts":[{"label":"Заложить мемориал","cost":{"cr":300},"risk":"sure","bad":0,"outs":[{"p":1,"text":"Церемония собрала весь город. Люди гордятся своей планетой.","fx":{"mood":[15,72]}}]},{"label":"Скромная табличка","cost":{"cr":80},"risk":"sure","bad":0,"outs":[{"p":1,"text":"Табличку открыли без шума.","fx":{"mood":[4,24]}}]},{"label":"Отказать — деньги нужны фронту","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Сенатор недоволен и пожаловался в комитет.","fx":{"income":[-10,24]}}]}]}'::jsonb),
('r_auditor', 'republic', 'senate', false, 1, 2, '{"title":"Ревизор Сената","text":"На {planet} прибыл ревизор комитета по ассигнованиям. Проверяет счета гарнизона и задаёт неудобные вопросы.","opts":[{"label":"Открыть все книги","cost":null,"risk":"gamble","bad":70,"outs":[{"p":7,"text":"Ревизор нашёл мелкие недочёты, но в целом доволен.","fx":{"cr":-100}},{"p":3,"text":"Ревизор отметил образцовый порядок — сектор получил премию.","fx":{"cr":250}}]},{"label":"Угостить ревизора","cost":{"cr":150},"risk":"gamble","bad":40,"outs":[{"p":6,"text":"Проверка прошла гладко.","fx":{}},{"p":4,"text":"Ревизор принял угощение за взятку. Скандал!","fx":{"mood":[-15,48],"income":[-10,24]}}]},{"label":"Затянуть проверку","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Ревизор застрял на неделю — и всё это время мешал работе.","fx":{"income":[-10,48]}}]}]}'::jsonb),
('r_padawan', 'republic', 'jedi', false, 1, 2, '{"title":"Падаван ищет храм","text":"Юный падаван прилетел на {planet} по зову видения: где-то в горах — забытое святилище джедаев. Просит проводников.","opts":[{"label":"Дать проводников","cost":{"cr":120},"risk":"sure","bad":0,"outs":[{"p":1,"text":"Отряд ушёл в горы. Вестей пока нет.","fx":{"next":"r_padawan_temple"}}]},{"label":"Дать только карту","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Падаван поблагодарил и ушёл один. Люди восхищены его смелостью.","fx":{"mood":[5,24]}}]},{"label":"Отговорить — в горах опасно","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Падаван отложил поиски. Орден, возможно, разочарован.","fx":{}}]}]}'::jsonb),
('r_leave', 'republic', 'clone', false, 1, 1, '{"title":"Клоны просят увольнительную","text":"Рота с {planet} третью неделю без отдыха. Сержант просит сутки увольнительной для бойцов.","opts":[{"label":"Дать увольнительную","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Бойцы отдохнули в кантинах — торговцы довольны.","fx":{"income":[10,24],"mood":[5,24]}}]},{"label":"Отказать — война не ждёт","cost":null,"risk":"gamble","bad":100,"outs":[{"p":7,"text":"Рота держится, но устала.","fx":{"mood":[-5,24]}},{"p":3,"text":"Уставший патруль проморгал банду мародёров.","fx":{"raid":3}}]},{"label":"Устроить праздник в казармах","cost":{"cr":150},"risk":"sure","bad":0,"outs":[{"p":1,"text":"Праздник удался — рота рвётся в бой.","fx":{"mood":[10,48]}}]}]}'::jsonb),
('r_smugglers', 'republic', 'smuggler', false, 1, 1, '{"title":"Контрабандисты в космопорту","text":"Таможня {planet} задержала грузовик с незадекларированными энергоячейками. Капитан предлагает «решить вопрос по-тихому».","opts":[{"label":"Конфисковать груз","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Ячейки ушли на склад гарнизона.","fx":{"res":{"cells":50},"mood":[3,24]}}]},{"label":"Взять откуп","cost":null,"risk":"gamble","bad":40,"outs":[{"p":6,"text":"Капитан заплатил и улетел.","fx":{"cr":200}},{"p":4,"text":"О сделке узнали жители — пошли слухи о продажных властях.","fx":{"cr":200,"mood":[-15,48]}}]},{"label":"Нанять капитана","cost":{"cr":100},"risk":"sure","bad":0,"outs":[{"p":1,"text":"Контрабандист будет возить грузы для гарнизона.","fx":{"income":[10,48]}}]}]}'::jsonb),
('r_fever', 'republic', 'plague', false, 1, 2, '{"title":"Болотная лихорадка","text":"В нижних кварталах {planet} вспышка лихорадки. Медики просят карантин и лекарства.","opts":[{"label":"Закупить лекарства","cost":{"cr":250},"risk":"sure","bad":0,"outs":[{"p":1,"text":"Вспышку остановили за два дня.","fx":{"mood":[5,24]}}]},{"label":"Закрыть кварталы на карантин","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Болезнь не ушла дальше, но кварталы стоят.","fx":{"extract":[-15,24],"mood":[-5,24]}}]},{"label":"Ничего не делать","cost":null,"risk":"gamble","bad":50,"outs":[{"p":5,"text":"Обошлось — лихорадка утихла сама.","fx":{}},{"p":5,"text":"Болезнь выкосила смены на шахтах.","fx":{"extract":[-25,48],"mood":[-15,48]}}]}]}'::jsonb),
('r_harvest', 'republic', 'festival', false, 1, 1, '{"title":"Праздник урожая","text":"Фермеры {planet} собрали лучший урожай за десять лет и зовут гарнизон на праздник.","opts":[{"label":"Профинансировать праздник","cost":{"cr":150},"risk":"sure","bad":0,"outs":[{"p":1,"text":"Праздник гремел три дня. Город любит своих защитников.","fx":{"mood":[15,72]}}]},{"label":"Отправить почётный караул","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Клоны в парадной броне — лучшая часть праздника.","fx":{"mood":[6,48]}}]},{"label":"Закупить излишки зерна","cost":{"cr":100},"risk":"sure","bad":0,"outs":[{"p":1,"text":"Склады пополнились свежим продовольствием.","fx":{"res":{"food":70}}}]}]}'::jsonb),
('r_pirates', 'republic', 'pirates', false, 1, 1, '{"title":"Пираты у системы","text":"Сенсоры {planet} засекли стаю пиратских истребителей. Они требуют «пошлину за спокойствие».","opts":[{"label":"Заплатить","cost":{"cr":200},"risk":"sure","bad":0,"outs":[{"p":1,"text":"Пираты ушли искать добычу в другом месте.","fx":{}}]},{"label":"Встретить огнём","cost":null,"risk":"gamble","bad":40,"outs":[{"p":6,"text":"Пиратов отогнали, двое сбиты — трофеи на складе.","fx":{"res":{"durasteel":40}}},{"p":4,"text":"Часть пиратов прорвалась к поверхности.","fx":{"raid":4}}]},{"label":"Предложить им службу","cost":{"cr":100},"risk":"luck","bad":0,"outs":[{"p":5,"text":"Пираты приняли деньги и охраняют маршрут.","fx":{"income":[10,48]}},{"p":5,"text":"Пираты взяли деньги и исчезли.","fx":{}}]}]}'::jsonb),
('r_lab', 'republic', 'science', false, 1, 2, '{"title":"Лаборатория просит грант","text":"Инженеры из университета {planet} предлагают новый способ очистки руды. Им нужен грант на испытания.","opts":[{"label":"Выдать грант","cost":{"cr":250},"risk":"sure","bad":0,"outs":[{"p":1,"text":"Испытания начались. Результат будет завтра.","fx":{"next":"r_lab_result"}}]},{"label":"Дать сырьё вместо денег","cost":{"res":{"ore":40}},"risk":"luck","bad":0,"outs":[{"p":6,"text":"Скромные испытания дали скромный результат.","fx":{"extract":[10,24]}},{"p":4,"text":"На малом объёме метод не сработал.","fx":{}}]},{"label":"Отказать","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Инженеры разочарованы.","fx":{"mood":[-3,24]}}]}]}'::jsonb),
('r_storm', 'republic', 'weather', false, 1, 2, '{"title":"Буря над равниной","text":"Метеослужба {planet} предупреждает: к поселению идёт пыльная буря. До удара — несколько часов.","opts":[{"label":"Свернуть добычу и укрыться","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Буря прошла — никто не пострадал, но смены потеряны.","fx":{"extract":[-15,12]}}]},{"label":"Укрепить купола","cost":{"res":{"durasteel":30}},"risk":"sure","bad":0,"outs":[{"p":1,"text":"Купола выдержали, работа не остановилась.","fx":{}}]},{"label":"Работать дальше","cost":null,"risk":"gamble","bad":50,"outs":[{"p":5,"text":"Буря прошла стороной. Повезло.","fx":{}},{"p":5,"text":"Буря снесла вышки и навесы.","fx":{"extract":[-30,24],"mood":[-10,24]}}]}]}'::jsonb),
('r_loan', 'republic', 'bank', false, 1, 2, '{"title":"Предложение банка","text":"Представитель Межгалактического банковского клана — нейтрального, как он уверяет, — предлагает {planet} кредит на развитие.","opts":[{"label":"Взять кредит","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Деньги поступили на счёт. Через сутки придёт счёт.","fx":{"cr":600,"next":"r_loan_due"}}]},{"label":"Взять половину","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Скромный кредит, скромный долг.","fx":{"cr":300,"next":"r_loan_due_small"}}]},{"label":"Отказаться","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Банкир вежливо откланялся.","fx":{}}]}]}'::jsonb),
('r_leaflets', 'republic', 'politics', false, 1, 2, '{"title":"Листовки сепаратистов","text":"Ночью на {planet} разбросали листовки: «Республика забирает ваших сыновей и ваш хлеб». Кто-то их печатает.","opts":[{"label":"Найти типографию","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Следы ведут в портовый квартал.","fx":{"next":"r_leaflets_press"}}]},{"label":"Ответить своей кампанией","cost":{"cr":120},"risk":"sure","bad":0,"outs":[{"p":1,"text":"Плакаты Республики и раздача пайков сделали своё дело.","fx":{"mood":[8,48]}}]},{"label":"Не обращать внимания","cost":null,"risk":"gamble","bad":40,"outs":[{"p":6,"text":"Листовки быстро забыли.","fx":{}},{"p":4,"text":"Слухи разошлись по кантинам.","fx":{"mood":[-10,48]}}]}]}'::jsonb),
('r_shield', 'republic', 'factory', false, 1, 2, '{"title":"Сбой генератора щита","text":"Генератор щита над {planet} сбоит. Техники просят время и детали.","opts":[{"label":"Заменить узел","cost":{"res":{"electronics":30}},"risk":"sure","bad":0,"outs":[{"p":1,"text":"Щит снова держит ровно.","fx":{}}]},{"label":"Чинить своими силами","cost":null,"risk":"gamble","bad":100,"outs":[{"p":6,"text":"Техники справились, но остановили часть цехов.","fx":{"extract":[-10,24]}},{"p":4,"text":"Ремонт затянулся, мародёры заметили брешь.","fx":{"raid":3}}]},{"label":"Отложить ремонт","cost":null,"risk":"gamble","bad":50,"outs":[{"p":5,"text":"Щит пока держится.","fx":{}},{"p":5,"text":"Пока щит мигал, банда прорвалась к окраинам.","fx":{"raid":4,"mood":[-5,24]}}]}]}'::jsonb),
('r_reporter', 'republic', 'politics', false, 1, 2, '{"title":"Репортёр Голонета","text":"Известный репортёр Голонета хочет снять сюжет о жизни {planet} во время войны.","opts":[{"label":"Провести экскурсию","cost":null,"risk":"risky","bad":30,"outs":[{"p":7,"text":"Сюжет вышел тёплым — к планете потянулись торговцы.","fx":{"income":[10,48]}},{"p":3,"text":"Репортёр снял и неприглядное: пустые склады и усталых людей.","fx":{"mood":[-5,24]}}]},{"label":"Показать только парадное","cost":{"cr":100},"risk":"sure","bad":0,"outs":[{"p":1,"text":"Красивый сюжет о сильной планете.","fx":{"mood":[5,24],"income":[5,24]}}]},{"label":"Отказать","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Репортёр уехал, бурча о цензуре.","fx":{}}]}]}'::jsonb),
('r_deserter', 'republic', 'clone', false, 1, 2, '{"title":"Клон-дезертир","text":"На окраине {planet} поймали клона без жетона. Он ушёл из части и живёт у фермеров, называет себя по имени.","opts":[{"label":"Вернуть в строй","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Клон вернулся в часть. Фермеры провожали его со слезами.","fx":{"gift":"inf","mood":[-5,24]}}]},{"label":"Оставить фермерам","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Фермеры благодарны — у них новый помощник.","fx":{"mood":[8,48],"extract":[5,24]}}]},{"label":"Передать военной полиции","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Дело закрыто по уставу.","fx":{}}]}]}'::jsonb),
('r_guild', 'republic', 'trade', false, 1, 2, '{"title":"Контракт гильдии","text":"Торговая гильдия предлагает {planet} годовой контракт на поставку руды по твёрдой цене.","opts":[{"label":"Подписать","cost":{"res":{"ore":50}},"risk":"sure","bad":0,"outs":[{"p":1,"text":"Первая партия ушла, гильдия заплатила честно.","fx":{"cr":450}}]},{"label":"Торговаться","cost":null,"risk":"luck","bad":0,"outs":[{"p":5,"text":"Гильдия уступила — цена выше.","fx":{"income":[12,48]}},{"p":5,"text":"Гильдия ушла к соседям.","fx":{}}]},{"label":"Отказаться","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Руда остаётся своим заводам.","fx":{}}]}]}'::jsonb),
('r_cache', 'republic', 'military', false, 1, 1, '{"title":"Тайник с оружием","text":"Дети на {planet} нашли в пещере ящики с бластерами времён старой войны.","opts":[{"label":"Изъять для гарнизона","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Оружие проверили и раздали ополчению.","fx":{"gift":"inf"}}]},{"label":"Разобрать на металл","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Склад пополнился.","fx":{"res":{"durasteel":45}}}]},{"label":"Наградить детей","cost":{"cr":50},"risk":"sure","bad":0,"outs":[{"p":1,"text":"Родители и учителя в восторге от щедрости гарнизона.","fx":{"mood":[8,48]}}]}]}'::jsonb),
('r_pacifists', 'republic', 'politics', false, 1, 2, '{"title":"Протест пацифистов","text":"На главной площади {planet} сидячий протест: «Нет войне, нет клонам». Протестующих всё больше.","opts":[{"label":"Выслушать лидеров","cost":null,"risk":"risky","bad":30,"outs":[{"p":7,"text":"Разговор снял напряжение.","fx":{"mood":[5,24]}},{"p":3,"text":"Лидеры потребовали невозможного — протест разросся.","fx":{"extract":[-10,24]}}]},{"label":"Разогнать","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Площадь пуста, но город затаил обиду.","fx":{"mood":[-15,72]}}]},{"label":"Переждать","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Через два дня протест сошёл на нет, но работа шла вполсилы.","fx":{"income":[-10,48]}}]}]}'::jsonb),
('r_barman', 'republic', 'spy', false, 1, 2, '{"title":"Бармен-информатор","text":"Бармен кантины на {planet} намекает, что знает, где сепаратисты прячут склад. Просит плату.","opts":[{"label":"Заплатить","cost":{"cr":150},"risk":"luck","bad":0,"outs":[{"p":6,"text":"Наводка верная — склад взят.","fx":{"res":{"cells":40,"electronics":20}}},{"p":4,"text":"Бармен продал байку. Склад давно пуст.","fx":{}}]},{"label":"Надавить","cost":null,"risk":"gamble","bad":50,"outs":[{"p":5,"text":"Бармен заговорил бесплатно.","fx":{"res":{"cells":30}}},{"p":5,"text":"Бармен обиделся — кантина перестала пускать клонов.","fx":{"mood":[-8,48]}}]},{"label":"Отказаться","cost":null,"risk":"sure","bad":0,"outs":[{"p":1,"text":"Бармен пожал плечами.","fx":{}}]}]}'::jsonb),
